import { Component } from '@angular/core';
import {VideoBackgroundComponent} from "@good/elements/video-background";
import {TranslocoModule} from "@jsverse/transloco";

@Component({
    selector: 'gd-home',
    standalone: true,
    imports: [
        VideoBackgroundComponent,
        TranslocoModule
    ],
    template: `
        <section id="home" 
                 class="min-h-screen flex items-center justify-center relative"
                 role="banner"
                 aria-labelledby="home-heading">
            <gd-video-background/>
            
            <!-- Main hero content -->
            <div class="relative z-10 text-center text-white px-4 sm:px-6 lg:px-8">
                <header class="max-w-4xl mx-auto">
                    <h1 id="home-heading" class="text-4xl sm:text-5xl md:text-6xl lg:text-7xl font-bold mb-6 font-playfair">
                        ALXNDRA
                    </h1>
                    <p class="text-xl sm:text-2xl md:text-3xl opacity-90 mb-8 max-w-3xl mx-auto">
                        {{ 'heroSubtitle' | transloco }}
                    </p>
                    <div class="flex flex-col sm:flex-row gap-4 justify-center items-center">
                        <button class="px-8 py-4 bg-gradient-to-r from-orange-500 to-red-500 hover:from-orange-600 hover:to-red-600 focus:from-orange-600 focus:to-red-600 text-white font-semibold rounded-lg transition-all duration-300 transform hover:scale-105 focus:scale-105 focus:outline-none focus:ring-2 focus:ring-orange-400/50 shadow-lg hover:shadow-xl"
                                (click)="scrollToServices()"
                                [attr.aria-label]="'myServices' | transloco">
                            {{ 'myServices' | transloco }}
                        </button>
                        <button class="px-8 py-4 border-2 border-white hover:bg-white hover:text-black focus:bg-white focus:text-black text-white font-semibold rounded-lg transition-all duration-300 focus:outline-none focus:ring-2 focus:ring-white/50"
                                (click)="scrollToContact()"
                                [attr.aria-label]="'getInTouch' | transloco">
                            {{ 'getInTouch' | transloco }}
                        </button>
                    </div>
                </header>
            </div>
        </section>
    `
})
export class HomeComponent {
  scrollToServices() {
    const servicesElement = document.getElementById('services');
    if (servicesElement) {
      servicesElement.scrollIntoView({ behavior: 'smooth' });
    }
  }

  scrollToContact() {
    const contactElement = document.getElementById('contact');
    if (contactElement) {
      contactElement.scrollIntoView({ behavior: 'smooth' });
    }
  }
}
