import {Component} from '@angular/core';
import {RouterLink} from "@angular/router";

@Component({
    selector: 'gd-logo',
    imports: [
        RouterLink
    ],
    template: `
        <div class="absolute right-12 top-4 z-50 cursor-pointer md:block hidden" 
             [routerLink]="'/'"
             role="banner"
             aria-label="Return to home page">
            <div class="relative">
                <!-- Digital glitch background layers -->
                <div class="absolute inset-0 bg-gradient-to-r from-pink-500/20 to-cyan-400/20 blur-xl opacity-60" aria-hidden="true"></div>
                <div class="absolute inset-0 bg-gradient-to-l from-red-500/15 to-blue-400/15 blur-lg opacity-40" aria-hidden="true"></div>

                <!-- Main logo text with multiple glitch effects -->
                <span class="font-rubik-glitch text-5xl font-normal text-white tracking-wider relative select-none user-select-none px-4 py-2 block digital-flicker neon-pulse">
                    <span class="relative z-10">ALXNDRA</span>
                    <!-- RGB shift overlay - hidden from screen readers -->
                    <span class="absolute inset-0 text-pink-500 opacity-70 rgb-shift mix-blend-screen" aria-hidden="true">ALXNDRA</span>
                    <span class="absolute inset-0 text-cyan-400 opacity-70 rgb-shift mix-blend-screen" aria-hidden="true"
                          style="animation-delay: 0.05s;">ALXNDRA</span>
                </span>
            </div>
        </div>
        
        <!-- Mobile centered logo -->
        <div class="fixed top-4 left-1/2 transform -translate-x-1/2 z-50 cursor-pointer md:hidden" 
             [routerLink]="'/'"
             role="banner"
             aria-label="Return to home page">
            <div class="relative">
                <!-- Digital glitch background layers -->
                <div class="absolute inset-0 bg-gradient-to-r from-pink-500/20 to-cyan-400/20 blur-xl opacity-60" aria-hidden="true"></div>
                <div class="absolute inset-0 bg-gradient-to-l from-red-500/15 to-blue-400/15 blur-lg opacity-40" aria-hidden="true"></div>

                <!-- Main logo text with multiple glitch effects -->
                <span class="font-rubik-glitch text-3xl sm:text-4xl font-normal text-white tracking-wider relative select-none user-select-none px-3 py-1 block digital-flicker neon-pulse">
                    <span class="relative z-10">ALXNDRA</span>
                    <!-- RGB shift overlay - hidden from screen readers -->
                    <span class="absolute inset-0 text-pink-500 opacity-70 rgb-shift mix-blend-screen" aria-hidden="true">ALXNDRA</span>
                    <span class="absolute inset-0 text-cyan-400 opacity-70 rgb-shift mix-blend-screen" aria-hidden="true"
                          style="animation-delay: 0.05s;">ALXNDRA</span>
                </span>
            </div>
        </div>
    `
})
export class Logo {}
