import {Component, ElementRef, ViewChild, AfterViewInit} from '@angular/core';

@Component({
    selector: 'gd-video-background',
    template: `
        <div class="video-background-container">
            <video
                    #backgroundVideo
                    autoplay
                    loop
                    muted
                    playsinline
                    preload="auto"
                    aria-hidden="true"
                    aria-label="Decorative background video"
                    class="video-background">
                <source src="videos/background_web.mp4" type="video/mp4">
            </video>
        </div>
    `,
    styles: [`
        .video-background-container {
            position: fixed;
            top: 0;
            left: 0;
            width: 100vw;
            height: 100vh;
            z-index: -10;
            overflow: hidden;
        }
        
        .video-background {
            position: absolute;
            top: 50%;
            left: 50%;
            min-width: 100%;
            min-height: 100%;
            width: auto;
            height: auto;
            transform: translate(-50%, -50%);
            object-fit: cover;
            pointer-events: none;
        }
        
        /* Ensure video covers full screen on all devices */
        @media (max-aspect-ratio: 16/9) {
            .video-background {
                width: 100%;
                height: auto;
            }
        }
        
        @media (min-aspect-ratio: 16/9) {
            .video-background {
                width: auto;
                height: 100%;
            }
        }
    `]
})
export class VideoBackgroundComponent implements AfterViewInit {
    @ViewChild('backgroundVideo') videoElement!: ElementRef<HTMLVideoElement>;

    ngAfterViewInit() {
        const video = this.videoElement.nativeElement;

        // Ensure the video is muted before attempting to play
        video.muted = true;
        video.defaultMuted = true;

        // Force video to cover full screen
        this.adjustVideoSize();

        // Listen for resize events to maintain full screen coverage
        window.addEventListener('resize', () => this.adjustVideoSize());

        // Try to play the video
        const playPromise = video.play();

        if (playPromise !== undefined) {
            playPromise.catch(error => {
                console.log('Auto-play was prevented:', error);
                // If autoplay fails, we can try to play on user interaction
                document.addEventListener('click', () => {
                    video.play().catch(e => console.log('Video play failed:', e));
                }, { once: true });
            });
        }
    }

    private adjustVideoSize() {
        const video = this.videoElement?.nativeElement;
        if (!video) return;

        const container = video.parentElement;
        if (!container) return;

        const containerAspect = container.clientWidth / container.clientHeight;
        const videoAspect = video.videoWidth / video.videoHeight;

        if (containerAspect > videoAspect) {
            video.style.width = '100%';
            video.style.height = 'auto';
        } else {
            video.style.width = 'auto';
            video.style.height = '100%';
        }
    }
}
