import { Component } from '@angular/core';
import {AnimateOnScroll} from "primeng/animateonscroll";
import {TranslocoModule} from "@jsverse/transloco";

@Component({
  selector: 'gd-equipment',
  standalone: true,
  imports: [
    AnimateOnScroll,
    TranslocoModule
  ],
  template: `
    <section id="equipment" 
             class="mt-4 section min-h-screen flex items-center justify-center bg-gradient-to-br from-gray-900 to-black relative px-4 sm:px-6 lg:px-8"
             role="main"
             aria-labelledby="equipment-heading">
      <div class="text-center text-white z-10 w-full max-w-7xl">
        <h1 id="equipment-heading" class="text-3xl sm:text-4xl md:text-5xl lg:text-6xl font-bold mb-6 sm:mb-8 font-playfair">{{ 'equipment' | transloco }}</h1>
        <p class="text-lg sm:text-xl opacity-80 mb-8 sm:mb-12 max-w-2xl mx-auto">{{ 'equipmentSubtitle' | transloco }}</p>
        
        <!-- Equipment Grid with improved responsive design -->
        <div class="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4 sm:gap-6 md:gap-8 w-full max-w-6xl"
             role="region"
             aria-label="Equipment categories">
            @for (device of equipmentList; track device.id) {
                <article class="bg-white/10 backdrop-blur-sm p-4 sm:p-6 rounded-lg group hover:bg-white/20 focus-within:bg-white/25 transition-all duration-300 border border-transparent hover:border-white/20 focus-within:border-white/30"
                         pAnimateOnScroll 
                         enterClass="animate-slide-in-up"
                         [attr.tabindex]="0"
                         [attr.aria-labelledby]="'equipment-title-' + device.id"
                         [attr.aria-describedby]="'equipment-desc-' + device.id"
                         role="button"
                         class="focus:outline-none focus:ring-2 focus:ring-orange-400 focus:ring-offset-2 focus:ring-offset-gray-900">
                    <div class="flex flex-col h-full">
                        <div class="mb-4">
                            <i [class]="device.icon + ' pi text-3xl sm:text-4xl text-orange-400 mb-3 sm:mb-4 block'" aria-hidden="true"></i>
                            <h2 [id]="'equipment-title-' + device.id" class="text-lg sm:text-xl md:text-2xl font-semibold mb-2 sm:mb-3 md:mb-4">{{ device.titleKey | transloco }}</h2>
                            <p [id]="'equipment-desc-' + device.id" class="text-sm sm:text-base opacity-90 mb-3 sm:mb-4 flex-grow">{{ device.descriptionKey | transloco }}</p>
                        </div>
                        @if (device.equipment && device.equipment.length > 0) {
                            <div class="mt-auto">
                                <h3 class="text-md font-medium mb-2 opacity-90">{{ 'equipmentLabel' | transloco }}:</h3>
                                <ul class="text-xs sm:text-sm opacity-70 space-y-1" role="list">
                                    @for (eq of device.equipment; track eq) {
                                        <li class="flex items-center justify-center" role="listitem">{{ eq }}</li>
                                    }
                                </ul>
                            </div>
                        }
                    </div>
                </article>
            }
        </div>
        
        <!-- Equipment categories for screen readers -->
        <div class="sr-only">
          <h2>Equipment Categories:</h2>
          <ul>
            @for (equipment of equipmentList; track equipment.id) {
              <li>{{ equipment.titleKey | transloco }}: {{ equipment.descriptionKey | transloco }}</li>
            }
          </ul>
        </div>
      </div>
    </section>
  `
})
export class EquipmentComponent {
  equipmentList = [
    {
      id: 1,
      titleKey: 'djSystems',
      descriptionKey: 'djSystemsDesc',
      icon: 'pi-headphones',
      color: 'text-cyan-400',
      equipment: ['Pioneer XDJ-XZ DJ Controller', 'Pioneer CDJ-3000 DJ Controller', 'Pioneer DJ DJM-A9']
    },
    {
      id: 2,
      titleKey: 'audio',
      descriptionKey: 'audioDesc',
      icon: 'pi-volume-up',
      color: 'text-red-400',
      equipment: ['Metro ES215', 'GloboStar PA FDB K112BAS', 'Vonyx PA VX210']
    },
    {
      id: 3,
      titleKey: 'microphones',
      descriptionKey: 'microphonesDesc',
      icon: 'pi-microphone',
      color: 'text-yellow-400',
      equipment: ['BT-233 pro', 'Maono', 'Lechpol']
    }
  ];
}
