import {Component, computed, inject, OnDestroy} from '@angular/core';
import {DrawerModule} from "primeng/drawer";
import {ButtonModule} from "primeng/button";
import {CommonModule} from '@angular/common';
import {Logo} from "@good/elements/logo";
import {ScrollNavigationComponent} from "@good/elements/scroll-navigation";
import {TranslocoService, TranslocoModule} from "@jsverse/transloco";
import {Subscription, take} from "rxjs";

@Component({
    selector: 'gd-root',
    standalone: true,
    imports: [DrawerModule, ButtonModule, CommonModule, Logo, ScrollNavigationComponent, TranslocoModule],
    template: `
        <!-- Logo -->
        <gd-logo />
        
        <!-- Language Toggle Button - Main Page -->
        <button
                (click)="toggleLanguage()"
                [attr.aria-label]="(currentLang() === 'en' ? 'switchLanguage' : 'switchLanguage') | transloco"
                class="fixed top-3 right-3 md:top-4 md:left-20 z-50 w-12 h-12 sm:w-14 sm:h-14 rounded-full bg-black/20 hover:bg-black/30 focus:bg-black/30 backdrop-blur-sm border border-white/20 hover:border-white/40 focus:border-white/40 text-white transition-all duration-300 flex items-center justify-center focus:outline-none focus:ring-2 focus:ring-white/50"
                type="button">
            <span class="text-xs sm:text-sm font-semibold tracking-wider">
                {{ currentLang() === 'en' ? 'ΕΛ' : 'EN' }}
            </span>
        </button>
        
        <!-- Desktop Navigation Drawer -->
        <p-drawer position="right"
                  [(visible)]="visible"
                  [header]="'navigationMenu' | transloco"
                  [style]="{'width': drawerWidth(), 'background': 'rgba(0, 0, 0, 0.95)', 'backdrop-filter': 'blur(10px)'}"
                  [modal]="true"
                  [dismissible]="true"
                  [closeOnEscape]="true"
                  styleClass="custom-drawer hidden md:block">
            <div class="flex flex-col space-y-6 sm:space-y-8 p-4 sm:p-6 h-full">
                <nav class="flex flex-col gap-6 sm:gap-8" role="navigation" aria-label="Main navigation">
                    @for (item of routerItems; track item.id) {
                        <a (click)="scrollToSection(item.sectionId); visible = false"
                           class="relative block py-3 sm:py-4 transition-all duration-300 cursor-pointer group focus:outline-none focus:ring-2 focus:ring-white/50 rounded-lg"
                           [attr.aria-label]="'Navigate to ' + (item.labelKey | transloco) + ' section'"
                           tabindex="0"
                           role="button"
                           (keydown.enter)="scrollToSection(item.sectionId); visible = false"
                           (keydown.space)="scrollToSection(item.sectionId); visible = false">
                            <span class="font-playfair text-2xl sm:text-3xl md:text-4xl font-semibold text-white tracking-wide transition-all duration-300 relative z-10 group-hover:text-gray-100 group-hover:translate-x-2 group-focus:text-gray-100 group-focus:translate-x-2">
                                {{ item.labelKey | transloco }}
                            </span>
                            <div class="absolute bottom-0 left-0 h-1 w-0 bg-gradient-to-r from-red-400 via-cyan-400 to-blue-400 rounded transition-all duration-400 ease-out group-hover:w-full group-focus:w-full group-active:animate-pulse shadow-lg shadow-red-400/30"></div>
                        </a>
                    }
                </nav>

                <!-- Quick Actions - Desktop Only -->
                <div class="mt-auto pt-6 border-t border-white/20">
                    <h3 class="text-lg font-semibold text-white mb-4">{{ 'quickActions' | transloco }}</h3>
                    <div class="space-y-3">
                        <button class="w-full px-4 py-2 bg-white/10 hover:bg-white/20 focus:bg-white/20 backdrop-blur-sm rounded-lg text-white transition-all duration-300 focus:outline-none focus:ring-2 focus:ring-white/50"
                                (click)="scrollToSection('contact'); visible = false"
                                [attr.aria-label]="'contactUs' | transloco">
                            <i class="pi pi-envelope mr-2" aria-hidden="true"></i>
                            {{ 'contactUs' | transloco }}
                        </button>
                        <button class="w-full px-4 py-2 bg-white/10 hover:bg-white/20 focus:bg-white/20 backdrop-blur-sm rounded-lg text-white transition-all duration-300 focus:outline-none focus:ring-2 focus:ring-white/50"
                                (click)="scrollToSection('gallery'); visible = false"
                                [attr.aria-label]="'viewGallery' | transloco">
                            <i class="pi pi-images mr-2" aria-hidden="true"></i>
                            {{ 'viewGallery' | transloco }}
                        </button>
                    </div>
                </div>
                <!-- Desktop Credit Text inside panel -->
                <div class="text-center">
                    <div class="text-sm text-white/40 tracking-wider origin-center whitespace-nowrap font-light">
                        {{ 'craftedBy' | transloco }}
                    </div>
                </div>
            </div>
        </p-drawer>
        <!-- Desktop Menu Toggle Button -->
        <button
                [attr.aria-label]="visible ? 'Close navigation menu' : 'Open navigation menu'"
                [attr.aria-expanded]="visible"
                (click)="visible = !visible"
                [class]="'fixed top-3 sm:top-4 left-3 sm:left-4 z-50 w-12 h-12 sm:w-14 sm:h-14 rounded-full bg-black/20 hover:bg-black/30 focus:bg-black/30 backdrop-blur-sm border border-white/20 hover:border-white/40 focus:border-white/40 text-white transition-all duration-300 flex items-center justify-center focus:outline-none focus:ring-2 focus:ring-white/50 hidden md:flex ' + (visible ? 'rotate-90' : '')"
                type="button">
            <i [class]="'pi text-lg sm:text-xl transition-transform duration-300 ' + (!visible ? 'pi-bars' : 'pi-times')"
               [attr.aria-hidden]="true"></i>
        </button>

        <!-- Scroll Navigation Component -->
        <gd-scroll-navigation></gd-scroll-navigation>
    `,
    styles: [`
        /* Custom drawer styles for better mobile experience */
        :host ::ng-deep .custom-drawer .p-drawer-content {
            padding: 0;
        }
        
        :host ::ng-deep .custom-drawer .p-drawer-header {
            background: rgba(0, 0, 0, 0.8);
            border-bottom: 1px solid rgba(255, 255, 255, 0.1);
            color: white;
        }

        /* Enhanced focus styles for better accessibility */
        button:focus-visible,
        a:focus-visible {
            outline: 2px solid rgba(255, 255, 255, 0.8);
            outline-offset: 2px;
        }
    `]
})
export class App implements OnDestroy {

    visible = false;
    translocoService = inject(TranslocoService);
    currentLang = computed(() => this.translocoService.getActiveLang());
    private subscription?: Subscription | null;

    routerItems = [
        { id: 0, sectionId: 'home', labelKey: 'home' },
        { id: 1, sectionId: 'equipment', labelKey: 'equipment' },
        { id: 2, sectionId: 'services', labelKey: 'services' },
        { id: 3, sectionId: 'gallery', labelKey: 'gallery' },
        { id: 4, sectionId: 'contact', labelKey: 'contact' }
    ];

    drawerWidth = computed(() =>  window.innerWidth < 768 ? '85vw' : '400px')

    scrollToSection(sectionId: string) {
        const element = document.getElementById(sectionId);
        if (element) {
            element.scrollIntoView({
                behavior: 'smooth',
                block: 'start'
            });
        }
    }

    toggleLanguage() {
        // Ensure new active lang is loaded
        this.subscription?.unsubscribe();
        const newLang = this.translocoService.getActiveLang() === 'en' ? 'el' : 'en';
        console.log(newLang);
        this.subscription = this.translocoService
            .load(newLang)
            .pipe(take(1))
            .subscribe(() => {
                this.translocoService.setActiveLang(newLang);
            });
    }



    ngOnDestroy() {
        this.subscription?.unsubscribe();
        this.subscription = null;
    }
}
