import { Component } from '@angular/core';
import {AnimateOnScroll} from "primeng/animateonscroll";
import {TranslocoModule} from "@jsverse/transloco";

@Component({
    selector: 'gd-services',
    standalone: true,
    imports: [
        AnimateOnScroll,
        TranslocoModule
    ],
    template: `
        <section id="services"
                 class="section min-h-screen flex items-center justify-center bg-black bg-opacity-90 relative px-4 sm:px-6 lg:px-8"
                 role="main"
                 aria-labelledby="services-heading">
            <div class="text-center text-white z-10 w-full max-w-7xl">
                <h1 id="services-heading" class="text-3xl sm:text-4xl md:text-5xl lg:text-6xl font-bold mb-6 sm:mb-8 font-playfair">{{ 'services' | transloco }}</h1>
                <p class="text-lg sm:text-xl opacity-80 mb-8 sm:mb-12 max-w-2xl mx-auto">{{ 'servicesSubtitle' | transloco }}</p>
                
                <!-- Enhanced responsive grid with better mobile support -->
                <div class="grid grid-cols-2 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 xl:grid-cols-5 gap-3 sm:gap-4 lg:gap-6 w-full max-w-7xl">
                    @for (service of services; track service.id) {
                        <div class="bg-white/10 backdrop-blur-sm p-3 sm:p-4 md:p-6 rounded-lg aspect-square flex flex-col items-center justify-center hover:bg-white/20 focus-within:bg-white/25 transition-all duration-300 group cursor-pointer border border-transparent hover:border-white/20 focus-within:border-white/30"
                             pAnimateOnScroll 
                             enterClass="animate-flip-in">
                            <button class="w-full h-full flex flex-col items-center justify-center text-white focus:outline-none focus:ring-2 focus:ring-white/50 rounded-lg"
                                    [attr.aria-label]="'Select ' + (service.titleKey | transloco) + ' service'">
                                <i [class]="service.icon + ' pi text-2xl sm:text-3xl md:text-4xl mb-2 sm:mb-3 md:mb-4 transition-transform duration-300 group-hover:scale-110 group-focus-within:scale-110 ' + service.color" 
                                   [attr.aria-hidden]="true"></i>
                                <h2 class="text-xs sm:text-sm md:text-base lg:text-lg xl:text-xl font-semibold mb-1 sm:mb-2 md:mb-3 text-center leading-tight px-1">
                                    {{ service.titleKey | transloco }}
                                </h2>
                                
                                <!-- Show description on larger screens only -->
                                <p class="opacity-80 text-xs md:text-sm text-center leading-tight px-2 hidden lg:block transition-opacity duration-300">
                                    {{ service.descriptionKey | transloco }}
                                </p>
                                
                                <!-- Show abbreviated description on medium screens -->
                                <p class="opacity-80 text-xs text-center leading-tight px-2 hidden md:block lg:hidden">
                                    {{ service.shortDescriptionKey | transloco }}
                                </p>
                            </button>
                        </div>
                    }
                </div>
                
                <!-- Screen reader friendly service list -->
                <div class="sr-only">
                    <h2>Available Services:</h2>
                    <ul>
                        @for (service of services; track service.id) {
                            <li>{{ service.titleKey | transloco }}: {{ service.descriptionKey | transloco }}</li>
                        }
                    </ul>
                </div>
            </div>
        </section>
    `
})
export class ServicesComponent {
    services = [
        {
            id: 1,
            icon: 'pi-volume-up',
            titleKey: 'audioEquipmentService',
            descriptionKey: 'audioEquipmentDesc',
            shortDescriptionKey: 'audioEquipmentShort',
            color: 'text-green-400'
        },
        {
            id: 2,
            icon: 'pi-play',
            titleKey: 'professionalDJ',
            descriptionKey: 'professionalDJDesc',
            shortDescriptionKey: 'professionalDJShort',
            color: 'text-red-400'
        },
        {
            id: 3,
            icon: 'pi-file-edit',
            titleKey: 'lyricWriting',
            descriptionKey: 'lyricWritingDesc',
            shortDescriptionKey: 'lyricWritingShort',
            color: 'text-yellow-400'
        },
        {
            id: 4,
            icon: 'pi-microphone',
            titleKey: 'guestVocalist',
            descriptionKey: 'guestVocalistDesc',
            shortDescriptionKey: 'guestVocalistShort',
            color: 'text-pink-400'
        },
        {
            id: 5,
            icon: 'pi-users',
            titleKey: 'eventDancers',
            descriptionKey: 'eventDancersDesc',
            shortDescriptionKey: 'eventDancersShort',
            color: 'text-indigo-400'
        }
    ];
}
