import { Component } from '@angular/core';
import {AnimateOnScroll} from "primeng/animateonscroll";
import {TranslocoModule} from "@jsverse/transloco";

@Component({
    selector: 'gd-contact',
    standalone: true,
    imports: [
        AnimateOnScroll,
        TranslocoModule
    ],
    template: `
        <section id="contact"
                 class="section min-h-screen flex items-center justify-center bg-gradient-to-br bg-black bg-opacity-90 relative px-4 sm:px-6 lg:px-8 pb-16 sm:pb-20 md:pb-24"
                 role="main"
                 aria-labelledby="contact-heading">
            <div class="text-center text-white z-10 w-full max-w-4xl" pAnimateOnScroll enterClass="animate-fade-in-down"
                 leaveClass="animate-fade-out-up">
                <h1 id="contact-heading" class="text-3xl sm:text-4xl md:text-5xl lg:text-6xl font-bold mb-6 sm:mb-8 font-playfair">{{ 'contact' | transloco }}</h1>
                <p class="text-lg sm:text-xl opacity-80 mb-8 sm:mb-12 max-w-2xl mx-auto">{{ 'contactSubtitle' | transloco }}</p>
                
                <div class="grid grid-cols-1 sm:grid-cols-2 gap-4 sm:gap-6 md:gap-8 max-w-2xl mx-auto">
                    <article class="bg-white/10 backdrop-blur-sm p-4 sm:p-6 rounded-lg hover:bg-white/20 focus-within:bg-white/25 transition-all duration-300 group border border-transparent hover:border-white/20 focus-within:border-white/30" 
                             pAnimateOnScroll enterClass="animate-slide-in-left"
                             role="article">
                        <div class="flex flex-col items-center text-center h-full">
                            <i class="pi pi-envelope text-2xl sm:text-3xl mb-3 sm:mb-4 text-orange-400 transition-transform duration-300 group-hover:scale-110 group-focus-within:scale-110" aria-hidden="true"></i>
                            <h2 class="text-lg sm:text-xl font-semibold">{{ 'emailLabel' | transloco }}</h2>
                            <div class="flex-grow flex items-center justify-center w-full">
                                <a href="mailto:alexgountiou&#64;gmail.com" 
                                   class="text-base sm:text-lg hover:text-orange-400 focus:text-orange-400 transition-colors duration-300 focus:outline-none focus:ring-2 focus:ring-orange-400/50 rounded px-2 py-1"
                                   [attr.aria-label]="'emailAriaLabel' | transloco">
                                    alexgountiou&#64;gmail.com
                                </a>
                            </div>
                        </div>
                    </article>
                    
                    <article class="bg-white/10 backdrop-blur-sm p-4 sm:p-6 rounded-lg hover:bg-white/20 focus-within:bg-white/25 transition-all duration-300 group border border-transparent hover:border-white/20 focus-within:border-white/30" 
                             pAnimateOnScroll enterClass="animate-slide-in-right"
                             role="article">
                        <div class="flex flex-col items-center text-center">
                            <i class="pi pi-map-marker text-2xl sm:text-3xl mb-3 sm:mb-4 text-orange-400 transition-transform duration-300 group-hover:scale-110 group-focus-within:scale-110" aria-hidden="true"></i>
                            <h2 class="text-sm sm:text-sm font-semibold mb-2 sm:mb-3">{{ 'locationLabel' | transloco }}</h2>
                            <div class="w-full max-w-xs sm:max-w-sm aspect-video rounded-lg overflow-hidden">
                                <iframe src="https://www.google.com/maps/embed?pb=!1m17!1m12!1m3!1d3042.7852717875326!2d21.819062876005408!3d40.30272647145822!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m2!1m1!2zNDDCsDE4JzA5LjgiTiAyMcKwNDknMTcuOSJF!5e0!3m2!1sel!2sgr!4v1757011832961!5m2!1sel!2sgr" 
                                        width="100%" 
                                        height="100%" 
                                        style="border:0;" 
                                        allowfullscreen="" 
                                        loading="lazy" 
                                        referrerpolicy="no-referrer-when-downgrade"
                                        [title]="'mapTitle' | transloco">
                                </iframe>
                            </div>
                        </div>
                    </article>
                </div>

                <!-- Additional contact methods -->
                <div class="mt-8 sm:mt-12">
                    <h2 class="text-xl sm:text-2xl font-semibold mb-4 sm:mb-6">{{ 'followMeLabel' | transloco }}</h2>
                    <div class="flex justify-center space-x-4 sm:space-x-6">
                        @for (social of socialLinks; track social.id) {
                            <a [href]="social.url" 
                               [attr.aria-label]="'Visit our ' + social.name + ' page'"
                               class="w-12 h-12 sm:w-14 sm:h-14 bg-white/10 backdrop-blur-sm rounded-full flex items-center justify-center hover:bg-white/20 focus:bg-white/25 transition-all duration-300 border border-transparent hover:border-white/20 focus:border-white/30 focus:outline-none focus:ring-2 focus:ring-white/50 group"
                               target="_blank"
                               rel="noopener noreferrer">
                                <i [class]="'pi ' + social.icon + ' text-lg sm:text-xl transition-transform duration-300 group-hover:scale-110 group-focus:scale-110 ' + social.color" 
                                   [attr.aria-hidden]="true"></i>
                            </a>
                        }
                    </div>
                </div>
            </div>
        </section>
    `
})
export class ContactComponent {
    socialLinks = [
        {
            id: 1,
            name: 'Instagram',
            url: 'https://www.instagram.com/alxndragood',
            icon: 'pi-instagram',
            color: 'text-pink-400'
        },
        {
            id: 2,
            name: 'Facebook',
            url: 'https://www.facebook.com/people/Alxndra-good-music/61579424007051',
            icon: 'pi-facebook',
            color: 'text-blue-400'
        },
        {
            id: 3,
            name: 'TikTok',
            url: 'https://www.tiktok.com/@alxndragoodmusic',
            icon: 'pi-tiktok',
            color: 'text-purple-400'
        },
        {
            id: 4,
            name: 'Youtube',
            url: 'https://www.youtube.com/@alxndragood1673',
            icon: 'pi-youtube',
            color: 'text-red-400'
        }
    ];
}
